//! One record per driver: what it answers to, and its life on a device.
//!
//! A record is two halves:
//!
//! - **Ids** ([`DriverIds`], [`crate::DRIVERS`]): generated by `build.rs` from
//!   the driver's `hwbus.ids` lines, one entry per driver name. Nothing else
//!   names a driver's ids.
//! - **Ops** ([`Ops`]): `probe`, `unbind`, `power` (suspend/resume) and
//!   `reset`, written next to the driver by its host. A host implements
//!   [`Host`]: the kernel's ops are calls into the driver crates, a ring-3
//!   host's are calls on the driver's endpoint. The shape is the same.
//!
//! [`native_drivers!`](crate::native_drivers) hands the host the generated
//! list, so the host's record table is built from it and not kept by hand: a
//! driver in the table without ops does not compile.
//!
//! [`Records`] is the bus's [`Drivers`] over a record table and an
//! environment ([`Env`]). An unbind is not taken on the driver's word: after
//! it, the environment says what the device still holds ([`Held`]: its
//! interrupt line, live DMA, its register window), and anything left keeps
//! the device bound ([`crate::UnbindError::Leaked`]).

use crate::bus::{Drivers, Handle, ProbeError};
use crate::device::Device;
pub use crate::tables::DriverIds;

/// Who runs a driver's ops, and over what.
pub trait Host: 'static {
    /// What an op is given: the host's resources for the bind in progress
    /// (the kernel's PCI bring-up lends its configuration space for one
    /// stage, so the environment borrows).
    type Env<'a>: Env;
}

/// One op of a driver on one device.
pub type Op<H> = for<'a, 'b> fn(&'b mut <H as Host>::Env<'a>, Handle, &Device) -> Result<(), ProbeError>;

/// How a driver lets go of a device.
pub enum Unbind<H: Host> {
    /// Quiesce the device (its DMA stopped and confirmed, in-flight work
    /// ended with an error), unbind its interrupt line and forget its window,
    /// so the device can be bound again or handed to ring 3.
    Op(Op<H>),
    /// Hardware the kernel drives outside the bus (the console, the
    /// interrupt controllers, the PCI host): never released.
    Pinned,
    /// The driver has no unbind yet; the device stays bound.
    Unsupported,
}

/// What a driver does across a system suspend.
pub enum Power<H: Host> {
    /// Take the device down (stop it, park its queues) and bring it back.
    Op { suspend: Op<H>, resume: Op<H> },
    /// Nothing to save: the binding only records that the kernel drives the
    /// hardware, whose own bring-up restores it.
    Stateless,
    /// The driver cannot be taken down: a suspend is refused while the
    /// device is bound.
    Unsupported,
}

impl<H: Host> Clone for Unbind<H> {
    fn clone(&self) -> Self {
        *self
    }
}
impl<H: Host> Copy for Unbind<H> {}

impl<H: Host> Clone for Power<H> {
    fn clone(&self) -> Self {
        *self
    }
}
impl<H: Host> Copy for Power<H> {}

/// A driver's ops.
pub struct Ops<H: Host> {
    /// Bind the driver to the device.
    pub probe: Op<H>,
    pub unbind: Unbind<H>,
    pub power: Power<H>,
    /// Stop the device, confirm the stop and program it again: what the
    /// recovery policy's `Reset` verdict runs (`azos_drv_api::recovery`);
    /// `None` when the driver has no reset, and a timeout latches it dead.
    pub reset: Option<Op<H>>,
}

/// One driver: its generated ids and its host's ops.
pub struct Record<H: Host> {
    pub ids: &'static DriverIds,
    pub ops: &'static Ops<H>,
}

impl<H: Host> Record<H> {
    pub fn name(&self) -> &'static str {
        self.ids.name
    }
}

/// What a device still holds through its host. Empty after a clean unbind.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub struct Held {
    /// An interrupt line bound to the driver.
    pub irq: Option<u32>,
    /// DMA the device may still perform (its queues are live).
    pub dma: bool,
    /// The driver still uses the register window.
    pub window: bool,
}

impl Held {
    pub const NONE: Held = Held { irq: None, dma: false, window: false };

    pub fn is_empty(&self) -> bool {
        *self == Held::NONE
    }
}

/// The host's side of a bind.
pub trait Env {
    /// The SoC resources of the device's node (clocks, resets, power
    /// domains, pin state), before the driver is asked
    /// ([`Drivers::resources`]).
    fn resources(&mut self, _driver: &str, _h: Handle, _dev: &Device) -> Result<(), ProbeError> {
        Ok(())
    }
    /// Give them back ([`Drivers::release`]).
    fn release(&mut self, _driver: &str, _h: Handle, _dev: &Device) {}
    /// What the device holds now, by the host's own books, not the driver's.
    fn held(&mut self, h: Handle, dev: &Device) -> Held;
}

/// The bus's drivers over a record table.
pub struct Records<'r, 'e, H: Host> {
    pub records: &'r [Record<H>],
    pub env: &'r mut H::Env<'e>,
}

/// The record named `name` in `records`.
pub fn find<'r, H: Host>(records: &'r [Record<H>], name: &str) -> Option<&'r Record<H>> {
    records.iter().find(|r| r.name() == name)
}

impl<H: Host> Records<'_, '_, H> {
    fn ops(&self, driver: &str) -> Result<&'static Ops<H>, ProbeError> {
        find(self.records, driver).map(|r| r.ops).ok_or(ProbeError::NoSuchDriver)
    }
}

impl<H: Host> Drivers for Records<'_, '_, H> {
    fn resources(&mut self, driver: &str, h: Handle, dev: &Device) -> Result<(), ProbeError> {
        self.env.resources(driver, h, dev)
    }

    fn release(&mut self, driver: &str, h: Handle, dev: &Device) {
        self.env.release(driver, h, dev)
    }

    fn probe(&mut self, driver: &str, h: Handle, dev: &Device) -> Result<(), ProbeError> {
        (self.ops(driver)?.probe)(self.env, h, dev)
    }

    fn remove(&mut self, driver: &str, h: Handle, dev: &Device) -> Result<(), ProbeError> {
        match self.ops(driver)?.unbind {
            Unbind::Op(f) => f(self.env, h, dev),
            Unbind::Pinned => Err(ProbeError::Pinned),
            Unbind::Unsupported => Err(ProbeError::Unsupported),
        }
    }

    fn held(&mut self, h: Handle, dev: &Device) -> Held {
        self.env.held(h, dev)
    }

    fn suspend(&mut self, driver: &str, h: Handle, dev: &Device) -> Result<(), ProbeError> {
        match self.ops(driver)?.power {
            Power::Op { suspend, .. } => suspend(self.env, h, dev),
            Power::Stateless => Ok(()),
            Power::Unsupported => Err(ProbeError::Unsupported),
        }
    }

    fn resume(&mut self, driver: &str, h: Handle, dev: &Device) -> Result<(), ProbeError> {
        match self.ops(driver)?.power {
            Power::Op { resume, .. } => resume(self.env, h, dev),
            Power::Stateless => Ok(()),
            Power::Unsupported => Err(ProbeError::Unsupported),
        }
    }
}
